create extension if not exists pgcrypto;
create table if not exists clients(id uuid primary key default gen_random_uuid(),name text not null,phone text,email text,company text,location text,notes text,created_at timestamptz not null default now());
create table if not exists service_packages(id uuid primary key default gen_random_uuid(),service_name text not null,package_name text not null,price numeric(12,2) not null default 0,labor_cost numeric(12,2) not null default 0,active boolean not null default true,created_at timestamptz not null default now(),unique(service_name,package_name));
create table if not exists quotes(id uuid primary key default gen_random_uuid(),client_id uuid references clients(id) on delete set null,customer_name text not null,phone text,location text,service_name text not null,package_name text not null,package_price numeric(12,2) not null,one_way_km numeric(10,2) not null default 0,travel_price numeric(12,2) not null default 0,extras_total numeric(12,2) not null default 0,final_price numeric(12,2) not null,vehicle_cost numeric(12,2) not null default 0,labor_cost numeric(12,2) not null default 0,equipment_cost numeric(12,2) not null default 600,other_cost numeric(12,2) not null default 0,estimated_profit numeric(12,2) not null default 0,deposit_amount numeric(12,2) not null default 0,remaining_amount numeric(12,2) not null default 0,status text not null default 'taslak' check(status in('taslak','gonderildi','kabul','reddedildi','iptal')),notes text,created_at timestamptz not null default now());
create table if not exists jobs(id uuid primary key default gen_random_uuid(),quote_id uuid references quotes(id) on delete set null,client_id uuid references clients(id) on delete set null,customer_name text not null,phone text,location text,service_name text not null,package_name text,scheduled_at timestamptz not null,delivery_at timestamptz,total_price numeric(12,2) not null default 0,deposit_amount numeric(12,2) not null default 0,paid_amount numeric(12,2) not null default 0,remaining_amount numeric(12,2) not null default 0,payment_status text not null default 'bekliyor' check(payment_status in('bekliyor','kismi','odendi','iade')),job_status text not null default 'planlandi' check(job_status in('planlandi','cekim_tamamlandi','kurguda','teslime_hazir','teslim_edildi','iptal')),notes text,created_at timestamptz not null default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),job_id uuid not null references jobs(id) on delete cascade,amount numeric(12,2) not null,payment_type text not null default 'diger',payment_method text,paid_at timestamptz not null default now(),notes text,created_at timestamptz not null default now());
create table if not exists expenses(id uuid primary key default gen_random_uuid(),job_id uuid references jobs(id) on delete set null,category text not null,amount numeric(12,2) not null,expense_at date not null default current_date,notes text,created_at timestamptz not null default now());
create table if not exists qr_menus(id uuid primary key default gen_random_uuid(),client_id uuid references clients(id) on delete set null,business_name text not null,slug text not null unique,package_name text not null check(package_name in('Start','Pro','Premium')),product_limit integer,update_allowance integer,updates_used integer not null default 0,renewal_price numeric(12,2) not null default 0,starts_at date not null default current_date,renews_at date not null,status text not null default 'taslak' check(status in('taslak','yayinda','pasif')),logo_url text,primary_color text,wifi_name text,wifi_password text,instagram text,whatsapp text,address text,created_at timestamptz not null default now());
create table if not exists menu_categories(id uuid primary key default gen_random_uuid(),menu_id uuid not null references qr_menus(id) on delete cascade,name text not null,sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists menu_items(id uuid primary key default gen_random_uuid(),category_id uuid not null references menu_categories(id) on delete cascade,name text not null,description text,price numeric(12,2) not null default 0,image_url text,badges text[] not null default '{}',available boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now());
create table if not exists menu_views(id bigint generated by default as identity primary key,menu_id uuid not null references qr_menus(id) on delete cascade,viewed_at timestamptz not null default now(),user_agent text,referrer text);
alter table clients enable row level security;alter table service_packages enable row level security;alter table quotes enable row level security;alter table jobs enable row level security;alter table payments enable row level security;alter table expenses enable row level security;alter table qr_menus enable row level security;alter table menu_categories enable row level security;alter table menu_items enable row level security;alter table menu_views enable row level security;
insert into service_packages(service_name,package_name,price,labor_cost) values('Drone Çekimi','Başlangıç',0,0),('Drone Çekimi','Premium',0,0),('Düğün & Nişan','Başlangıç',0,0),('Düğün & Nişan','Premium',0,0),('Emlak & Gayrimenkul','Başlangıç',0,0),('Emlak & Gayrimenkul','Premium',0,0),('Mekân & İşletme','Başlangıç',0,0),('Mekân & İşletme','Premium',0,0),('Organizasyon','Başlangıç',0,0),('Organizasyon','Premium',0,0),('Reklam & Tanıtım','Başlangıç',0,0),('Reklam & Tanıtım','Premium',0,0) on conflict(service_name,package_name) do nothing;
